import{_ as a,o as s,c as t,a5 as r}from"./chunks/framework.DrDMl0tG.js";const i="/assets/rayrai_visual_asset_support.DKBk_eQ0.png",_=JSON.parse('{"title":"Rayrai Example: Visual Asset Support","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_visual_asset_support.md","filePath":"sections/examples/rayrai/rayrai_visual_asset_support.md"}'),o={name:"sections/examples/rayrai/rayrai_visual_asset_support.md"};function l(d,e,n,p,c,u){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="rayrai-example-visual-asset-support" tabindex="-1">Rayrai Example: Visual Asset Support <a class="header-anchor" href="#rayrai-example-visual-asset-support" aria-label="Permalink to &quot;Rayrai Example: Visual Asset Support&quot;">​</a></h1><p><img src="'+i+'" alt="rayrai_visual_asset_support example"></p><p><em>The YCB objects are licensed under CC BY 4.0 and credited in <a href="./../../AssetCredits.html#ycb-objects">Asset Credits</a>.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Shows visual asset loading on realistic URDF assets with image textures. The example loads the textured ANYmal C URDF and several YCB object URDFs whose OBJ or DAE visual meshes reference texture image files, then renders them in rayrai.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_visual_asset_support</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_visual_asset_support</span></span></code></pre></div><p>On Windows, run <code>rayrai_visual_asset_support.exe</code> instead. This example renders in process with rayrai and does not need <code>rayrai_tcp_viewer</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads <code>rsc/anymal_c/urdf/anymal.urdf</code> and four YCB object URDFs from <code>rsc/ycb</code>.</li><li>Loads the textured visual meshes referenced from URDF <code>visual</code> tags.</li><li>Keeps visual assets and collision assets separate through URDF <code>visual</code> and <code>collision</code> tags.</li><li>Renders image textures from packaged mesh assets such as <code>rsc/anymal_c/meshes/*.jpg</code> and <code>rsc/ycb/*/google_16k/texture_map.png</code>.</li><li>Uses renderer-facing mesh assets for rayrai while RaiSim continues to use the collision geometry defined by the URDF.</li></ul>',13)])])}const m=a(o,[["render",l]]);export{_ as __pageData,m as default};
